-- ============================================================================
-- B5 FOLLOW-ON W1 (grade integrity): wellcorrelation.
--
-- Plan of record: docs/graded-field-audit/FOLLOW-ON-PROGRAMME.md section 4 and
-- the annotations in docs/graded-field-audit/annot/wellcorrelation.json. Owner
-- approved D1 to D7 as recommended, 2026-09-21.
--
-- BEGINNER
--   wells_with_top_b graded a count over four wells (3), guessable at 0.25 and
--   printed on the panel's TOP_B tile. It is replaced by a measured depth read
--   in the same Section explorer at a second, stated flattening: Ekene-3's TOP_B
--   displayed depth with BASE_SAND pinned to a 1560 m datum, 1628 - 10 = 1618 m.
--   The panel prints whole metres; tol 0.5 is half that unit and every other
--   TOP_B reading in that view (1620, 1621) fails.
--   RE-KEY wells_with_top_b (expected 3, tol 0)
--       -> w3_top_b_displayed_base_1560_m 'Ekene-3: TOP_B displayed depth, flattened on BASE_SAND at 1560 m' m, expected 1618.0, tol 0.5
--   PROMPT was: the structural relief on TOP_SAND, and how many wells the TOP_B
--   correlation line reaches.
--   PROMPT now: the structural relief on TOP_SAND, and Ekene-3's TOP_B displayed
--   depth once the section is re-flattened on BASE_SAND at a 1560 m datum.
--
-- INTERMEDIATE
--   wells_with_all_tops graded a count over four wells (3), guessable at 0.25
--   and printed on the default Flatten explorer tile. It is replaced by the
--   shallowest displayed depth at a second, stated flattening, TOP_SAND at a
--   1480 m datum, read from the same panel's "Shallowest displayed" tile:
--   Ekene-4 TOP_A at 1530 - 110 = 1420 m. The panel prints whole metres; tol 0.5
--   is half that unit and the next shallowest reading (Ekene-2 TOP_A 1427) and
--   the datum (1480) both fail.
--   RE-KEY wells_with_all_tops (expected 3, tol 0)
--       -> shallowest_displayed_sand_1480_m 'Shallowest displayed depth, flattened on TOP_SAND at 1480 m' m, expected 1420.0, tol 0.5
--   PROMPT was: the number of wells carrying all four tops, and the displayed
--   depth span of the section.
--   PROMPT now: the shallowest displayed depth once the section is re-flattened
--   on TOP_SAND at a 1480 m datum, and the displayed depth span of the section
--   back on the TOP_A datum.
--
-- WHAT DOES NOT MOVE. Every other field (key, label, unit, expected, tol and
-- position), the title, dataset, status and the row itself.
--
-- ATTEMPTS. Tiers whose graded key or tolerance moves:
-- wellcorrelation/beginner, wellcorrelation/intermediate. Before it writes,
-- the file counts academy_capstone_attempts on each and REFUSES if any exist,
-- unless D5 allowlists that tier with the exact attempt ids (allowlist:
-- empty). Stored scores are never touched.
--
-- GUARDS. Each row must hold EITHER its published prompt (by md5) and fields
-- (exact jsonb) as the post-20261023 scratch replay has them (it is
-- rewritten), OR its W1 form (left alone). Anything else raises and the whole
-- file rolls back. A file that will write first checks the round-off
-- post-state (20261023*) and refuses without it. Generated by
-- docs/graded-field-audit/w1_capstones.py. SAFE TO RE-RUN: a second run
-- writes nothing.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_ids      jsonb;
  v_extra    jsonb;
  v_allow    jsonb := '{}'::jsonb;  -- D5 allowlist: 'course/tier' -> attempt ids signed off
  v_s0       text;
  v_s1       text;
begin
  -- wellcorrelation / beginner
  select count(*) into v_n from public.academy_capstones where app_slug = 'wellcorrelation' and tier = 'beginner' and active;
  if v_n <> 1 then raise exception 'w1 wellcorrelation refused: wellcorrelation/beginner has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'bf1f50969809b7b8d1d582924456b0df' and fields = '[{"key": "w2_shift_m", "tol": 0.01, "unit": "m", "label": "Ekene-2: flattening shift", "expected": -65}, {"key": "w3_sand_thickness_m", "tol": 0.01, "unit": "m", "label": "Ekene-3: SAND zone thickness", "expected": 29}, {"key": "w4_base_sand_displayed_m", "tol": 0.01, "unit": "m", "label": "Ekene-4: BASE_SAND displayed depth (flattened)", "expected": 1525}, {"key": "sand_relief_m", "tol": 0.01, "unit": "m", "label": "TOP_SAND structural relief across the section", "expected": 49}, {"key": "wells_with_top_b", "tol": 0, "unit": "count", "label": "Wells the TOP_B correlation line reaches", "expected": 3}, {"key": "w1_top_b_displayed_m", "tol": 0.01, "unit": "m", "label": "Ekene-1: TOP_B displayed depth (flattened)", "expected": 1592}]'::jsonb then 'old'
              when md5(prompt) = '3a2dc1bcd2bd85910cfde760e7bcda89' and fields = '[{"key": "w2_shift_m", "tol": 0.01, "unit": "m", "label": "Ekene-2: flattening shift", "expected": -65}, {"key": "w3_sand_thickness_m", "tol": 0.01, "unit": "m", "label": "Ekene-3: SAND zone thickness", "expected": 29}, {"key": "w4_base_sand_displayed_m", "tol": 0.01, "unit": "m", "label": "Ekene-4: BASE_SAND displayed depth (flattened)", "expected": 1525}, {"key": "sand_relief_m", "tol": 0.01, "unit": "m", "label": "TOP_SAND structural relief across the section", "expected": 49}, {"key": "w3_top_b_displayed_base_1560_m", "tol": 0.5, "unit": "m", "label": "Ekene-3: TOP_B displayed depth, flattened on BASE_SAND at 1560 m", "expected": 1618.0}, {"key": "w1_top_b_displayed_m", "tol": 0.01, "unit": "m", "label": "Ekene-1: TOP_B displayed depth (flattened)", "expected": 1592}]'::jsonb then 'new'
              when md5(prompt) = 'b4026fc2b6e46a77a171906c69e1d6f4' and fields = '[{"key": "w2_shift_m", "tol": 0.01, "unit": "m", "label": "Ekene-2: flattening shift", "expected": -65}, {"key": "w3_sand_thickness_m", "tol": 0.01, "unit": "m", "label": "Ekene-3: SAND zone thickness", "expected": 29}, {"key": "w4_base_sand_displayed_m", "tol": 0.01, "unit": "m", "label": "Ekene-4: BASE_SAND displayed depth (flattened)", "expected": 1525}, {"key": "sand_relief_m", "tol": 0.01, "unit": "m", "label": "TOP_SAND structural relief across the section", "expected": 49}, {"key": "w3_top_b_displayed_base_1560_m", "tol": 0.5, "unit": "m", "label": "Ekene-3: TOP_B displayed depth, flattened on BASE_SAND at 1560 m", "expected": 1618.0}, {"key": "w1_top_b_displayed_m", "tol": 0.01, "unit": "m", "label": "Ekene-1: TOP_B displayed depth (flattened)", "expected": 1592}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'wellcorrelation' and tier = 'beginner' and active;
  if v_s0 = 'other' then
    raise exception 'w1 wellcorrelation refused: wellcorrelation/beginner matches neither its published form (prompt md5 bf1f50969809b7b8d1d582924456b0df) nor its W1 form (prompt md5 3a2dc1bcd2bd85910cfde760e7bcda89), with the fields this file was generated against';
  end if;

  -- wellcorrelation / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'wellcorrelation' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'w1 wellcorrelation refused: wellcorrelation/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'ea4ad6bdc1115832fbb3f2b1ed6c20dc' and fields = '[{"key": "w4_shift_m", "tol": 0.01, "unit": "m", "label": "Ekene-4: flattening shift", "expected": -80}, {"key": "w2_topsand_displayed_m", "tol": 0.01, "unit": "m", "label": "Ekene-2: TOP_SAND displayed depth", "expected": 1503}, {"key": "a_to_sand_w4_m", "tol": 0.01, "unit": "m", "label": "Ekene-4: TOP_A→TOP_SAND interval", "expected": 60}, {"key": "growth_range_m", "tol": 0.01, "unit": "m", "label": "A-to-SAND growth range (max − min)", "expected": 14}, {"key": "wells_with_all_tops", "tol": 0, "unit": "count", "label": "Wells carrying all four tops", "expected": 3}, {"key": "displayed_span_m", "tol": 0.01, "unit": "m", "label": "Displayed depth span of the section", "expected": 150}]'::jsonb then 'old'
              when md5(prompt) = 'ff93446f08c084743566694f406cf9d2' and fields = '[{"key": "w4_shift_m", "tol": 0.01, "unit": "m", "label": "Ekene-4: flattening shift", "expected": -80}, {"key": "w2_topsand_displayed_m", "tol": 0.01, "unit": "m", "label": "Ekene-2: TOP_SAND displayed depth", "expected": 1503}, {"key": "a_to_sand_w4_m", "tol": 0.01, "unit": "m", "label": "Ekene-4: TOP_A→TOP_SAND interval", "expected": 60}, {"key": "growth_range_m", "tol": 0.01, "unit": "m", "label": "A-to-SAND growth range (max − min)", "expected": 14}, {"key": "shallowest_displayed_sand_1480_m", "tol": 0.5, "unit": "m", "label": "Shallowest displayed depth, flattened on TOP_SAND at 1480 m", "expected": 1420.0}, {"key": "displayed_span_m", "tol": 0.01, "unit": "m", "label": "Displayed depth span of the section", "expected": 150}]'::jsonb then 'new'
              when md5(prompt) = '06340559816bd341fd61af8b492e735a' and fields = '[{"key": "w4_shift_m", "tol": 0.01, "unit": "m", "label": "Ekene-4: flattening shift", "expected": -80}, {"key": "w2_topsand_displayed_m", "tol": 0.01, "unit": "m", "label": "Ekene-2: TOP_SAND displayed depth", "expected": 1503}, {"key": "a_to_sand_w4_m", "tol": 0.01, "unit": "m", "label": "Ekene-4: TOP_A→TOP_SAND interval", "expected": 60}, {"key": "growth_range_m", "tol": 0.01, "unit": "m", "label": "A-to-SAND growth range (max − min)", "expected": 14}, {"key": "shallowest_displayed_sand_1480_m", "tol": 0.5, "unit": "m", "label": "Shallowest displayed depth, flattened on TOP_SAND at 1480 m", "expected": 1420.0}, {"key": "displayed_span_m", "tol": 0.01, "unit": "m", "label": "Displayed depth span of the section", "expected": 150}]'::jsonb then 'new'
              else 'other' end
    into v_s1 from public.academy_capstones where app_slug = 'wellcorrelation' and tier = 'intermediate' and active;
  if v_s1 = 'other' then
    raise exception 'w1 wellcorrelation refused: wellcorrelation/intermediate matches neither its published form (prompt md5 ea4ad6bdc1115832fbb3f2b1ed6c20dc) nor its W1 form (prompt md5 ff93446f08c084743566694f406cf9d2), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W1 form
  if v_s0 = 'new' and v_s1 = 'new' then
    raise notice 'w1 wellcorrelation: 0 of 2 row(s) written, all already applied';
    return;
  end if;

  -- the round-off batch (20261023*) must be applied first: its rows are this file's base
  if exists (select 1 from public.academy_capstones where app_slug = 'cementing' and tier = 'advanced' and active and md5(prompt) <> '7e7412057740dcb01936e298c2026745')
     or exists (select 1 from public.academy_capstones where app_slug = 'casingtubing' and tier = 'advanced' and active and md5(prompt) <> 'f7e6749b9be66d4dbc7e692745d656d7')
     or exists (select 1 from public.academy_capstones where app_slug = 'gaswell' and tier = 'advanced' and active and md5(prompt) <> '07f6076362de4a93714236cc10af4012')
     or exists (select 1 from public.academy_capstones where app_slug = 'wellcontrol' and tier = 'beginner' and active and md5(dataset) <> '228b1d1a73f0474291f6142741bab7b2')
     or exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                 where c.app_slug = 'fiscal' and c.tier = 'intermediate' and c.active and f->>'key' = 'psc_npv_musd'
                   and (f->>'tol')::float8 <> 0.05) then
    raise exception 'w1 wellcorrelation refused: the round-off batch (20261023*) is not applied on this database; apply it first (/root/roundoff-apply/apply.sh apply --prod)';
  end if;

  -- ATTEMPTS. A tier whose graded key or tolerance this file moves must hold no
  -- capstone attempt (a stored score is never re-scored, but a learner could be
  -- graded differently on a retry of the same brief), unless D5 allowlists it
  -- with the exact attempt ids signed off. Any other attempt refuses.
  if v_s0 = 'old' then
    select coalesce(jsonb_agg(a.id::text order by a.created_at, a.id), '[]'::jsonb) into v_ids
      from public.academy_capstone_attempts a where a.app_slug = 'wellcorrelation' and a.tier = 'beginner';
    if jsonb_array_length(v_ids) > 0 then
      if v_allow ? 'wellcorrelation/beginner' then
        select coalesce(jsonb_agg(x), '[]'::jsonb) into v_extra
          from jsonb_array_elements(v_ids) x where not (v_allow->'wellcorrelation/beginner') @> jsonb_build_array(x);
        if jsonb_array_length(v_extra) > 0 then
          raise exception 'w1 wellcorrelation refused: wellcorrelation/beginner holds % attempt(s) outside its D5 allowlist: %', jsonb_array_length(v_extra), v_extra;
        end if;
        raise notice 'w1 wellcorrelation: wellcorrelation/beginner holds % allowlisted attempt(s) (D5 sign-off); their stored scores are not touched', jsonb_array_length(v_ids);
      else
        raise exception 'w1 wellcorrelation refused: wellcorrelation/beginner holds % capstone attempt(s) (%) and this file moves its graded key or tolerance; sign the tier off under D5 (allowlist with these ids) or hold it', jsonb_array_length(v_ids), v_ids;
      end if;
    end if;
  end if;
  if v_s1 = 'old' then
    select coalesce(jsonb_agg(a.id::text order by a.created_at, a.id), '[]'::jsonb) into v_ids
      from public.academy_capstone_attempts a where a.app_slug = 'wellcorrelation' and a.tier = 'intermediate';
    if jsonb_array_length(v_ids) > 0 then
      if v_allow ? 'wellcorrelation/intermediate' then
        select coalesce(jsonb_agg(x), '[]'::jsonb) into v_extra
          from jsonb_array_elements(v_ids) x where not (v_allow->'wellcorrelation/intermediate') @> jsonb_build_array(x);
        if jsonb_array_length(v_extra) > 0 then
          raise exception 'w1 wellcorrelation refused: wellcorrelation/intermediate holds % attempt(s) outside its D5 allowlist: %', jsonb_array_length(v_extra), v_extra;
        end if;
        raise notice 'w1 wellcorrelation: wellcorrelation/intermediate holds % allowlisted attempt(s) (D5 sign-off); their stored scores are not touched', jsonb_array_length(v_ids);
      else
        raise exception 'w1 wellcorrelation refused: wellcorrelation/intermediate holds % capstone attempt(s) (%) and this file moves its graded key or tolerance; sign the tier off under D5 (allowlist with these ids) or hold it', jsonb_array_length(v_ids), v_ids;
      end if;
    end if;
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Flatten the section on TOP_SAND at a 1500 m datum and read the panel: report the flattening shifts, the SAND zone thickness, displayed depths under the datum, the structural relief on TOP_SAND, and Ekene-3''s TOP_B displayed depth once the section is re-flattened on BASE_SAND at a 1560 m datum.',
           fields = '[{"key": "w2_shift_m", "tol": 0.01, "unit": "m", "label": "Ekene-2: flattening shift", "expected": -65}, {"key": "w3_sand_thickness_m", "tol": 0.01, "unit": "m", "label": "Ekene-3: SAND zone thickness", "expected": 29}, {"key": "w4_base_sand_displayed_m", "tol": 0.01, "unit": "m", "label": "Ekene-4: BASE_SAND displayed depth (flattened)", "expected": 1525}, {"key": "sand_relief_m", "tol": 0.01, "unit": "m", "label": "TOP_SAND structural relief across the section", "expected": 49}, {"key": "w3_top_b_displayed_base_1560_m", "tol": 0.5, "unit": "m", "label": "Ekene-3: TOP_B displayed depth, flattened on BASE_SAND at 1560 m", "expected": 1618.0}, {"key": "w1_top_b_displayed_m", "tol": 0.01, "unit": "m", "label": "Ekene-1: TOP_B displayed depth (flattened)", "expected": 1592}]'::jsonb
     where app_slug = 'wellcorrelation' and tier = 'beginner' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 wellcorrelation refused: wellcorrelation/beginner updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '3a2dc1bcd2bd85910cfde760e7bcda89' and fields = '[{"key": "w2_shift_m", "tol": 0.01, "unit": "m", "label": "Ekene-2: flattening shift", "expected": -65}, {"key": "w3_sand_thickness_m", "tol": 0.01, "unit": "m", "label": "Ekene-3: SAND zone thickness", "expected": 29}, {"key": "w4_base_sand_displayed_m", "tol": 0.01, "unit": "m", "label": "Ekene-4: BASE_SAND displayed depth (flattened)", "expected": 1525}, {"key": "sand_relief_m", "tol": 0.01, "unit": "m", "label": "TOP_SAND structural relief across the section", "expected": 49}, {"key": "w3_top_b_displayed_base_1560_m", "tol": 0.5, "unit": "m", "label": "Ekene-3: TOP_B displayed depth, flattened on BASE_SAND at 1560 m", "expected": 1618.0}, {"key": "w1_top_b_displayed_m", "tol": 0.01, "unit": "m", "label": "Ekene-1: TOP_B displayed depth (flattened)", "expected": 1592}]'::jsonb)
        or (md5(prompt) = 'b4026fc2b6e46a77a171906c69e1d6f4' and fields = '[{"key": "w2_shift_m", "tol": 0.01, "unit": "m", "label": "Ekene-2: flattening shift", "expected": -65}, {"key": "w3_sand_thickness_m", "tol": 0.01, "unit": "m", "label": "Ekene-3: SAND zone thickness", "expected": 29}, {"key": "w4_base_sand_displayed_m", "tol": 0.01, "unit": "m", "label": "Ekene-4: BASE_SAND displayed depth (flattened)", "expected": 1525}, {"key": "sand_relief_m", "tol": 0.01, "unit": "m", "label": "TOP_SAND structural relief across the section", "expected": 49}, {"key": "w3_top_b_displayed_base_1560_m", "tol": 0.5, "unit": "m", "label": "Ekene-3: TOP_B displayed depth, flattened on BASE_SAND at 1560 m", "expected": 1618.0}, {"key": "w1_top_b_displayed_m", "tol": 0.01, "unit": "m", "label": "Ekene-1: TOP_B displayed depth (flattened)", "expected": 1592}]'::jsonb) from public.academy_capstones where app_slug = 'wellcorrelation' and tier = 'beginner' and active) is not true then
    raise exception 'w1 wellcorrelation refused: wellcorrelation/beginner does not read back as its W1 form';
  end if;

  if v_s1 = 'old' then
    update public.academy_capstones
       set prompt = 'Flatten the section on TOP_A at a 1450 m datum and study the A-to-SAND interval: report the Ekene-4 shift, the displayed TOP_SAND in Ekene-2, the interval thickness in Ekene-4, the growth range across the section, the shallowest displayed depth once the section is re-flattened on TOP_SAND at a 1480 m datum, and the displayed depth span of the section back on the TOP_A datum.',
           fields = '[{"key": "w4_shift_m", "tol": 0.01, "unit": "m", "label": "Ekene-4: flattening shift", "expected": -80}, {"key": "w2_topsand_displayed_m", "tol": 0.01, "unit": "m", "label": "Ekene-2: TOP_SAND displayed depth", "expected": 1503}, {"key": "a_to_sand_w4_m", "tol": 0.01, "unit": "m", "label": "Ekene-4: TOP_A→TOP_SAND interval", "expected": 60}, {"key": "growth_range_m", "tol": 0.01, "unit": "m", "label": "A-to-SAND growth range (max − min)", "expected": 14}, {"key": "shallowest_displayed_sand_1480_m", "tol": 0.5, "unit": "m", "label": "Shallowest displayed depth, flattened on TOP_SAND at 1480 m", "expected": 1420.0}, {"key": "displayed_span_m", "tol": 0.01, "unit": "m", "label": "Displayed depth span of the section", "expected": 150}]'::jsonb
     where app_slug = 'wellcorrelation' and tier = 'intermediate' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 wellcorrelation refused: wellcorrelation/intermediate updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'ff93446f08c084743566694f406cf9d2' and fields = '[{"key": "w4_shift_m", "tol": 0.01, "unit": "m", "label": "Ekene-4: flattening shift", "expected": -80}, {"key": "w2_topsand_displayed_m", "tol": 0.01, "unit": "m", "label": "Ekene-2: TOP_SAND displayed depth", "expected": 1503}, {"key": "a_to_sand_w4_m", "tol": 0.01, "unit": "m", "label": "Ekene-4: TOP_A→TOP_SAND interval", "expected": 60}, {"key": "growth_range_m", "tol": 0.01, "unit": "m", "label": "A-to-SAND growth range (max − min)", "expected": 14}, {"key": "shallowest_displayed_sand_1480_m", "tol": 0.5, "unit": "m", "label": "Shallowest displayed depth, flattened on TOP_SAND at 1480 m", "expected": 1420.0}, {"key": "displayed_span_m", "tol": 0.01, "unit": "m", "label": "Displayed depth span of the section", "expected": 150}]'::jsonb)
        or (md5(prompt) = '06340559816bd341fd61af8b492e735a' and fields = '[{"key": "w4_shift_m", "tol": 0.01, "unit": "m", "label": "Ekene-4: flattening shift", "expected": -80}, {"key": "w2_topsand_displayed_m", "tol": 0.01, "unit": "m", "label": "Ekene-2: TOP_SAND displayed depth", "expected": 1503}, {"key": "a_to_sand_w4_m", "tol": 0.01, "unit": "m", "label": "Ekene-4: TOP_A→TOP_SAND interval", "expected": 60}, {"key": "growth_range_m", "tol": 0.01, "unit": "m", "label": "A-to-SAND growth range (max − min)", "expected": 14}, {"key": "shallowest_displayed_sand_1480_m", "tol": 0.5, "unit": "m", "label": "Shallowest displayed depth, flattened on TOP_SAND at 1480 m", "expected": 1420.0}, {"key": "displayed_span_m", "tol": 0.01, "unit": "m", "label": "Displayed depth span of the section", "expected": 150}]'::jsonb) from public.academy_capstones where app_slug = 'wellcorrelation' and tier = 'intermediate' and active) is not true then
    raise exception 'w1 wellcorrelation refused: wellcorrelation/intermediate does not read back as its W1 form';
  end if;

  raise notice 'w1 wellcorrelation: % of 2 row(s) written, % already applied', v_written, 2 - v_written;
end $$;
